                _linear(x, layer) {
                    return Array(layer.weights[0].length).fill(0).map((_, j) => {
                        let sum = layer.bias[j];
                        for (let i = 0; i < x.length; i++) {
                            sum += x[i] * layer.weights[i][j];
                        }
                        return sum;
                    });
                }
