                            if (e1.type === 'line' && e2.type === 'line') {
                                const dx1 = e1.x2 - e1.x1, dy1 = e1.y2 - e1.y1;
                                const dx2 = e2.x2 - e2.x1, dy2 = e2.y2 - e2.y1;
                                F.push(dx1 * dx2 + dy1 * dy2);
                            }
                            break;
