    // Calculate cumulative parameter lengths
    let totalLength = 0;
    const cumulativeLengths = [0];
    segments.forEach(seg => {
      const len = seg.curve.length?.() || 1;
      totalLength += len;
      cumulativeLengths.push(totalLength);
    });

