        'C11000': { A: 85, B: 280, n: 0.32, C: 0.024, m: 1.08, T_melt: 1356 },
        'C17200': { A: 350, B: 500, n: 0.35, C: 0.020, m: 1.0, T_melt: 1338 },  // Beryllium Copper
        'C26000': { A: 120, B: 350, n: 0.38, C: 0.018, m: 1.05, T_melt: 1188 },  // Brass
