            this._findPairs(nodeA.left, nodeB.left, pairs);
            this._findPairs(nodeA.left, nodeB.right, pairs);
            this._findPairs(nodeA.right, nodeB.left, pairs);
            this._findPairs(nodeA.right, nodeB.right, pairs);
