        // Compute RMS in chatter band
        let bandEnergy = 0;
        for (let i = minBin; i <= maxBin && i < magnitude.length / 2; i++) {
            bandEnergy += magnitude[i] * magnitude[i];
        }
        const bandRMS = Math.sqrt(bandEnergy / (maxBin - minBin + 1));

