        const axis = depth % k;

        points.sort((a, b) => {
            const keys = ['x', 'y', 'z'];
            return a[keys[axis]] - b[keys[axis]];
        });

        const mid = Math.floor(points.length / 2);

        this.node = points[mid];
        this.axis = axis;
        this.left = new KDTree(points.slice(0, mid), depth + 1);
        this.right = new KDTree(points.slice(mid + 1), depth + 1);
