            const bx = c[0] - a[0], by = c[1] - a[1];

            const d = 2 * (ax * by - ay * bx);
            if (Math.abs(d) < 1e-10) return Infinity;

            const al = ax * ax + ay * ay;
            const bl = bx * bx + by * by;

            const ux = (by * al - ay * bl) / d;
            const uy = (ax * bl - bx * al) / d;

            return Math.sqrt(ux * ux + uy * uy);
