    const total = Object.keys(results).length;

    (typeof PRISM_CONSTANTS !== 'undefined' && PRISM_CONSTANTS.DEBUG) && console.log(`\n[PRISM Cross-Domain] Tests completed: ${passed}/${total} passed\n`);

    return results;
